/** Owner views of authoritative DayWorkers reads. No parallel payroll or ledger. */
import {e,link,Header} from './components.js';
import {exactDecimalString,exactMoney,cents,decimal} from './connected-adapter.js';
const card=body=>`<section class="card day-card">${body}</section>`;
const input=(label,name,value='',type='text',extra='')=>`<label>${e(label)}<input name="${e(name)}" type="${type}" value="${e(value??'')}" ${extra}></label>`;
const text=(label,name,value='',extra='')=>`<label>${e(label)}<textarea name="${e(name)}" dir="auto" ${extra}>${e(value??'')}</textarea></label>`;
const select=(label,name,items,value='',blank='Выберите')=>`<label>${e(label)}<select name="${e(name)}" required><option value="">${e(blank)}</option>${items.map(x=>`<option value="${e(x.value??x.id)}" ${String(x.value??x.id)===String(value)?'selected':''}>${e(x.label??x.name??x.display_name??x.original_name??x.code??'Без названия')}</option>`).join('')}</select></label>`;
const form=(kind,body,label)=>`<form data-form="${kind}" novalidate>${body}<p class="day-device-note" role="status">Черновик на этом устройстве. Отправка на сервер отдельно.</p><div class="form-error" role="alert"></div><div class="confirmation-bar"><button type="submit" class="btn primary full">${e(label)}</button></div></form>`;
export const dayOwnerState=value=>({PENDING:'Ожидает решения',APPROVED:'Одобрено',REJECTED:'Отклонено',CLARIFICATION_REQUIRED:'Нужно уточнение',APPROVE:'Одобрено',REVISE_APPROVE:'Одобрено с изменениями',REJECT:'Отклонено',CLARIFY:'Запрошено уточнение'})[value]||value;
export const dayNumber=value=>exactDecimalString(value)==null?'Неизвестно':exactDecimalString(value).replace('.',',');
const fact=(label,value)=>`<div class="fact-row"><dt>${e(label)}</dt><dd>${e(value??'Неизвестно')}</dd></div>`;
const facts=rows=>`<dl class="fact-list">${rows.map(x=>fact(...x)).join('')}</dl>`;
const originalFields=row=>row?.original?.fields||row?.source?.fields||{};
const actualFields=row=>({...originalFields(row),...row});
const original=row=>`<details class="day-original"><summary>Исходная форма · без изменений</summary>${facts(Object.entries(originalFields(row)).map(([key,value])=>[({people:'Человек, включая старшего',days:'Дней',work:'Работа',start_date:'Дата начала',event_date:'День работы',note:'Примечание',full_day:'Полный день',text:'Ответ',reason:'Причина',decision:'Решение'})[key]||key,value===''?'Не указано':value]))}<small>Введено: ${e(row?.original?.captured_at||row?.source?.captured_at||'Неизвестно')}</small></details>`;
const requestLink=r=>link(`<strong>${e(r.current_plan?.work||originalFields(r).work||'Заявка на работников')}</strong><small>${e(r.greenhouse_name||'Теплица')} · ${e(r.worker_name||'Владелец')} · ${e(dayOwnerState(r.state))}</small><span>${r.planned_people_days==null?'Запрошено '+e(dayNumber(r.requested_people_days)):'План '+e(dayNumber(r.planned_people_days))} · известно ${e(dayNumber(r.actual_people_days))} фактически, человеко-дней${r.unresolved_day_actual_ids?.length?' · есть дни с неизвестной длительностью':''}</span>`,'day-request/'+r.id,'list-row');
export function dayWorkersView(result) {
  const requests=result.requests||[],actuals=result.actuals||[];
  return Header('Дневные рабочие','Заявки, решения и фактическая работа',true)+
    `<div class="page-actions">${link('Записать факт без заявки','day-actual/new','btn primary')}${link('Новая плановая заявка','day-request-new','btn secondary')}${link('Проверить доступ к теплицам','day-scopes','btn secondary')}</div>`+
    card(`<h2>Заявки</h2>${requests.map(requestLink).join('')||'<p>Заявок пока нет. Это не подтверждённое отсутствие работ.</p>'}`)+
    card(`<h2>Фактически по дням</h2>${actuals.map(dayActualRow).join('')||'<p>Факты ещё не записаны.</p>'}`)+
    `<p class="note">План не создаёт начисление. Каждый фактический день проверяется отдельно; оплата проходит по существующему долгу.</p>`;
}
export function dayRequestFormView(draft,refs,choices=[]) {
  return Header('Плановая заявка','Три поля после выбора теплицы',true)+card(form('day-request',select('Проверенная теплица','greenhouse_id',refs.greenhouses||[],draft.greenhouse_id)+dayPlanFields(draft,choices)+`<details><summary>Дата и примечание · необязательно</summary>${input('Дата начала, если известна','start_date',draft.start_date,'date')}${text('Примечание','note',draft.note)}</details>`,'Сохранить заявку на сервере'));
}
export function dayPlanFields(draft,choices=[]){return `<div class="day-primary-fields">${input('Сколько человек, включая старшего','people',draft.people,'text','inputmode="numeric" required maxlength="6"')}${input('На сколько дней','days',draft.days,'text','inputmode="numeric" required maxlength="4"')}${/[\r\n]/.test(draft.work||'')?text('Какая работа','work',draft.work,'required maxlength="2000"'):input('Какая работа','work',draft.work,'text','required maxlength="2000" list="day-work-choices" autocomplete="off"')}<datalist id="day-work-choices">${choices.map(work=>`<option value="${e(work)}"></option>`).join('')}</datalist><small>Выберите прежнюю работу этой теплицы или введите свою. Это подсказки из истории, не справочник видов работ.</small></div>`;}
export function dayRequestView(r,back='day-workers') {
  const p=r.current_plan||r.original_plan||{},editable=['PENDING','CLARIFICATION_REQUIRED','APPROVED'].includes(r.state);
  return Header(p.work||'Заявка на работников',`${r.greenhouse_name||'Теплица'} · ${r.worker_name||'Владелец'}`)+link('Назад к работам',back,'section-link')+
    card(`<div class="status-line"><span class="tag">${e(dayOwnerState(r.state))}</span><span class="note">Сохранено на сервере</span></div><h2>План</h2>${facts([['Человек, включая старшего',p.people],['Дней',p.days],['Дата начала',p.start_date||'Не указана'],['Запрошено, человеко-дней',dayNumber(r.requested_people_days)],['Одобрено в плане, человеко-дней',r.planned_people_days==null?'Ещё не одобрено':dayNumber(r.planned_people_days)],['Известно фактически, человеко-дней',dayNumber(r.actual_people_days)],['Дни с неполной или неизвестной длительностью',r.unresolved_day_actual_ids?.length||0]])}${p.note?`<p dir="auto">${e(p.note)}</p>`:''}${editable?`<div class="page-actions">${[['APPROVE','Одобрить'],['REVISE_APPROVE','Изменить и одобрить'],['REJECT','Отклонить с причиной'],['CLARIFY','Запросить уточнение']].filter(([d])=>r.state!=='APPROVED'||d==='REVISE_APPROVE').map(([d,label])=>link(label,`day-decision/${r.id}/${d}`,'btn '+(d==='APPROVE'?'primary':'secondary'))).join('')}</div>`:''}${original(r)}`)+
    card(`<div class="card-header"><h2>Фактически по дням</h2>${link('Добавить день','day-actual/new/'+r.id,'section-link')}</div>${(r.actuals||[]).map(dayActualRow).join('')||'<p>Факт не записан. План не подставляется.</p>'}`)+
    card(`<h2>Решения и уточнения</h2>${(r.decisions||[]).map(d=>`<div class="list-row"><strong>${e(dayOwnerState(d.decision||d.source?.fields?.decision))}</strong><p dir="auto">${e(d.reason||d.source?.fields?.reason||'')}</p>${original(d)}</div>`).join('')}${(r.clarifications||[]).map(c=>`<div class="list-row"><strong>Ответ работника</strong><p dir="auto">${e(c.body||c.text||c.original?.fields?.text||c.source?.fields?.text||'')}</p></div>`).join('')||'<p class="note">Уточнений работника пока нет.</p>'}`);
}
export function dayDecisionView(r,decision,draft) {
  const p=r.original_plan||r.current_plan||{},edit=decision==='REVISE_APPROVE';
  return Header(dayOwnerState(decision),'Исходная заявка остаётся без изменений',true)+card(form('day-decision',`${draft.version_conflict?`<div class="notice" role="alert"><strong>Заявка изменилась после открытия формы.</strong>${facts([['Текущая работа',r.current_plan?.work],['Человек',r.current_plan?.people],['Дней',r.current_plan?.days],['Статус',dayOwnerState(r.state)]])}<label class="check-label"><input type="checkbox" name="reviewed_current" required><span>Я заново проверил текущую заявку и своё решение.</span></label></div>`:''}<input type="hidden" name="decision" value="${e(decision)}">${edit?dayPlanFields(draft)+input('Дата начала, если известна','start_date',draft.start_date,'date')+text('Примечание','note',draft.note):facts([['Работа',p.work],['Человек',p.people],['Дней',p.days],['Дата начала',p.start_date||'Не указана']])}${text(decision==='CLARIFY'?'Что нужно уточнить':decision==='REJECT'?'Причина отказа':'Комментарий к решению','reason',draft.reason,['REJECT','CLARIFY'].includes(decision)?'required':'')}<p class="note">Это решение по плану. Начисления и платежа не будет.</p>`,decision==='CLARIFY'?'Отправить вопрос':decision==='REJECT'?'Сохранить отказ':'Сохранить решение'));
}
export function dayActualRow(a) {
  const f=actualFields(a),replaced=!!(a.replacement_id||a.replaced_by_id||a.superseded_by_id||a.current===false||a.is_current===false);
  return link(`<strong>${e(f.event_date||'Дата неизвестна')} · ${e(dayNumber(f.people))} человек</strong><small>${e(a.greenhouse_name||'')} · ${e(f.work||'Работа')}</small><span class="tag">${replaced?'Заменён новым фактом':String(f.people)==='0'?'Никто не работал · начисления нет':a.accrual?.obligation_status==='reversed'||a.accrual?.status==='reversed'?'Начисление отменено':a.accrual?.correction_required||a.correction_required?'Нужно проверить исправление':a.accrual?'Начислено':f.full_day===true||f.full_day==='true'?'Полный день · проверить начисление':'Нужно уточнить полный день'}</span>`,'day-actual-detail/'+a.id,'list-row');
}
export function dayActualFormView(draft,refs,request=null,replaces=null) {
 const context=request||replaces,allocations=select('Где работала бригада?','allocation_mode',[{value:'same',label:'Все в выбранной теплице'},{value:'split',label:'Разделить по теплицам, с известным числом людей'},{value:'unknown',label:'Распределение неизвестно'}],draft.allocation_mode)+`<details><summary>Распределение по теплицам и известным частям</summary><p class="note">Укажите людей по известным теплицам. Общая бригада учитывается один раз. Незаполненная часть останется нераспределённой.</p>${(refs.greenhouses||[]).map(g=>input(g.name+' · человек при разделении','allocation_'+g.id,draft['allocation_'+g.id],'text','inputmode="numeric"')+`<label>Часть теплицы ${e(g.name)} · если достоверно известна<select name="part_id_${e(g.id)}"><option value="">Вся теплица / часть неизвестна</option>${(refs.references?.work_areas||[]).filter(p=>p.parent_id===g.id).map(p=>`<option value="${e(p.id)}" ${draft['part_id_'+g.id]===p.id?'selected':''}>${e(p.name)}</option>`).join('')}</select></label>`).join('')}</details>`;
 const body=(context?`<p class="day-context">${e(context.greenhouse_name||'Теплица')} · ${request?'По заявке':'Исправление прежнего факта'}</p>`:select('Теплица · контекст факта','greenhouse_id',refs.greenhouses||[],draft.greenhouse_id)+`<p class="note">Без плановой заявки. Предварительный план не создаётся.</p>`)+input('День работы','event_date',draft.event_date,'date','required')+input('Сколько человек работало, включая старшего','people',draft.people,'text','inputmode="numeric" required')+text('Какая работа выполнена','work',draft.work,'required')+select('Полный день подтверждён?','full_day',[{value:'true',label:'Да, полный день'},{value:'false',label:'Нет, неполный день'},{value:'unknown',label:'Неизвестно'}],draft.full_day)+allocations+text('Примечание','note',draft.note)+`<p class="note">Частичный день и неизвестная длительность сохраняются для проверки. Автоматического расчёта по часам или половине дня нет.</p>`;
 return Header(replaces?'Исправить фактический день':'Фактическая работа','Один день и фактическое число людей',true)+card(form('day-actual',body,'Сохранить факт'));
}
export function dayConfirmationView(actual,draft){return Header('Подтвердить фактическую работу','Без ставки, начисления и оплаты',true)+card(facts([['Теплица',actual.greenhouse_name],['День',actual.event_date],['Фактически человек',actual.people],['Работа',actual.work]])+form('day-confirmation',text('Результат проверки','note',draft.note)+`<label class="check-label"><input type="checkbox" name="confirmed" required><span>Подтверждаю этот факт. Финансовые условия будут проверены отдельно.</span></label>`,'Подтвердить только факт'));}
export function dayActualView(a,back='day-workers') {
  const f=actualFields(a),blocked=String(f.people)==='0'?[]:(a.accrual_blockers||[]),replaced=!!(a.replacement_id||a.replaced_by_id||a.superseded_by_id||a.current===false||a.is_current===false);
  return Header('Фактический день',a.greenhouse_name||'Теплица')+link('Назад к работам',back,'section-link')+card(`<span class="tag">Сохранено на сервере</span>${facts([['День работы',f.event_date],['Человек, включая старшего',f.people],['Работа',f.work],['Полный день',f.full_day===true||f.full_day==='true'?'Да':f.full_day===false||f.full_day==='false'?'Нет':'Неизвестно']])}${f.note?`<p dir="auto">${e(f.note)}</p>`:''}<h2>Где работала бригада</h2>${(a.allocations||[]).map(x=>facts([['Теплица',x.greenhouse_name||'Проверенная теплица'],['Часть',x.work_area_name||'Не указана'],['Человек',x.people]])).join('')}${facts([['Нераспределено человек',a.unallocated_people]])}${original(a)}`)+
    card(`<h2>Начисление и оплата</h2>${a.confirmation?'<p class="tag">Факт принят владельцем</p>':!replaced?link('Подтвердить только факт','day-confirmation/'+a.id,'btn secondary'):''}${a.accrual?.obligation_status==='reversed'||a.accrual?.status==='reversed'||a.accrual?.correction_required||a.correction_required?'<p class="notice">Связанное начисление отменено или требует исправления. Откройте финансовый документ; прежний факт не доказывает текущее начисление.</p>':''}${a.accrual?`${facts([['Начислено',`${dayNumber(a.accrual.amount??a.accrual.original_amount)} ${a.accrual.currency||''}`],['Кредитор',a.accrual.counterparty_name||'В финансовом документе'],['Основание ставки',a.accrual.rate_basis||a.accrual.source?.fields?.rate_basis||'В исходной форме начисления']])}${link('Открыть долг и отдельную оплату','money-document/'+a.accrual.obligation_id+'/'+encodeURIComponent('day-actual-detail/'+a.id),'btn primary')}<p class="note">Начисление не означает выплату. Выплата старшему не доказывает расчёт с каждым человеком.</p>`:replaced?'<p>Этот факт заменён. Начислять по нему нельзя.</p>':`${blocked.length?`<p class="notice">${e(blocked.map(dayAccrualBlocker).join(' · '))}</p>`:''}${String(f.people)==='0'?'<p class="notice">Никто не работал: 0 человеко-дней. Начисление не создаётся.</p>':link('Проверить начисление','day-accrual/'+a.id,'btn primary')}${link('Исправить этот факт','day-actual/replace/'+a.id,'btn secondary')}<p class="note">${String(f.people)==='0'?'Факт отсутствия работников сохранён. Ставка и кредитор не требуются.':'Нужны проверенный кредитор, ставка, её основание, валюта и счёт затрат. Оплата выполняется отдельно.'}</p>`}`);
}
export function dayAccrualBlocker(value){return ({ZERO_WORK_NO_ACCRUAL:'Никто не работал: начисление не создаётся',FULL_DAY_UNRESOLVED:'Полный день не подтверждён',ALLOCATION_INCOMPLETE:'Распределение людей по теплицам неполное',ACTUAL_REPLACED:'Факт заменён',EXPLICIT_CREDITOR_RATE_REVIEW_REQUIRED:'Нужно проверить кредитора, ставку и её основание',FULL_DAY_NOT_CONFIRMED:'Полный день не подтверждён',NOT_FULL_DAY:'Неполный день требует отдельного решения',ALREADY_ACCRUED:'Начисление уже существует',SUPERSEDED:'Факт заменён',REPLACED:'Факт заменён'})[value]||value;}
export function dayAccrualView(a,refs,draft) {
  const f=actualFields(a),full=f.full_day===true||f.full_day==='true',eligible=full&&Number(f.people)>0&&!a.accrual&&!a.replacement_id&&!a.replaced_by_id&&!a.superseded_by_id&&a.current!==false&&a.is_current!==false&&a.unallocated_people===0;
  return Header('Проверить начисление','Подтверждённый фактический день',true)+card(facts([['Теплица',a.greenhouse_name],['День',f.event_date],['Фактически человек',f.people],['Работа',f.work]])+(!eligible?'<p class="notice" role="alert">Начисление заблокировано. Нужен текущий факт полного дня с положительным числом людей без прежнего начисления. Неполный день, спор и исправление начисленного факта требуют решения владельца.</p>':form('day-accrual',select('Кому должны · проверенный кредитор','counterparty_id',refs.references?.counterparties||[],draft.counterparty_id)+input('Ставка за человека за полный день','daily_rate',draft.daily_rate,'text','inputmode="decimal" required')+text('Основание и дата действия ставки','rate_basis',draft.rate_basis,'required')+select('Валюта','currency',['TRY','USD','EUR','UAH'].map(value=>({value,label:value})),draft.currency)+select('Счёт учёта затрат','expense_account_id',(refs.references?.expense_accounts||[]).map(x=>({...x,id:x.id||x.ledger_account_id,label:(x.name||x.account_name||x.code||'Счёт затрат')+' · '+(x.currency||'')})),draft.expense_account_id)+input('Срок оплаты · если известен','due_date',draft.due_date,'date')+`<div data-day-accrual-review>${dayAccrualPreview(a,refs,draft)}</div><label class="check-label"><input type="checkbox" name="confirmed" required ${draft.confirmed==='on'?'checked':''}><span>Я проверил фактический полный день, кредитора, ставку и её основание. Создать долг и затраты по проверенному распределению фактической бригады. Денег сейчас не выплачивать.</span></label>`,'Подтвердить начисление')));
}
export function dayScopesView(result,draft) {
 const refs=result.references||{};
 return Header('Доступ работника к теплице','Только явное подтверждение владельца',true)+card(`<p>Заявки и факты доступны работнику только по проверенным теплицам. Имена не используются для угадывания назначения.</p>${(refs.scopes||[]).map(s=>`<div class="list-row"><strong>${e(s.worker_name||refs.workers?.find(w=>w.id===s.worker_id)?.display_name||'Работник')} · ${e(s.greenhouse_name||result.greenhouses?.find(g=>g.id===s.greenhouse_id)?.name||'Теплица')}</strong><small>${s.action==='REVOKE'||s.active===false?'Доступ отозван':'Назначение подтверждено'}</small></div>`).join('')||'<p>Нет подтверждённых назначений.</p>'}`)+card(form('day-scope',select('Работник','worker_id',refs.workers||[],draft.worker_id)+select('Теплица','greenhouse_id',result.greenhouses||[],draft.greenhouse_id)+select('Решение','action',[{value:'GRANT',label:'Подтвердить назначение'},{value:'REVOKE',label:'Отозвать доступ'}],draft.action)+text('Что проверено · основание','reason',draft.reason,'required'),'Сохранить проверенное назначение'));
}

export function dayAccrualPreview(actual,refs,draft){
 let rate;
 try{rate=exactMoney(draft.daily_rate);}catch{return '<p class="notice">Введите проверенную ставку. Сумма начисления пока неизвестна.</p>';}
 if(!draft.currency)return '<p class="notice">Выберите валюту. Сумма без валюты не подтверждается.</p>';
 const total=decimal(cents(rate)*BigInt(actual.people)),party=(refs.references?.counterparties||[]).find(x=>x.id===draft.counterparty_id),account=(refs.references?.expense_accounts||[]).find(x=>x.id===draft.expense_account_id);
 return `<section class="owner-review-effect" aria-label="Проверка суммы начисления"><h2>Проверьте начисление</h2>${facts([['Кредитор',party?.name||'Не выбран'],['Ставка на человека за полный день',dayNumber(rate)+' '+draft.currency],['Сумма нового начисления',dayNumber(total)+' '+draft.currency],['Счёт затрат',account?.name||'Не выбран']])}${account&&account.currency!==draft.currency?'<p class="bad">Валюта счёта не совпадает с валютой начисления.</p>':''}<h3>Распределение этой суммы</h3>${(actual.allocations||[]).map(x=>facts([['Теплица / часть',[x.greenhouse_name,x.work_area_name].filter(Boolean).join(' / ')||'Проверенное распределение'],['Человек',x.people],['Затраты',dayNumber(decimal(cents(rate)*BigInt(x.people)))+' '+draft.currency]])).join('')}<p class="note">Новый долг: ${e(dayNumber(total))} ${e(draft.currency)}. Сейчас выплачено: 0. Платёж будет отдельным действием.</p></section>`;
}
